package com.example.domain.model.i18n

internal object DuaTr1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Uyanırken", "Bizi öldürdükten (uyuttuktan) sonra dirilten Allah'a hamd olsun; dönüş de yalnız O'nadır.", "Uykudan uyanır uyanmaz Allah'a şükretmek için okunur.", "Peygamber ﷺ uyanınca bunu okurdu — güne şükür ve ahiret hatırlatmasıyla başlamak."),
        "dua_leaving_home" to DuaText("Evden çıkarken", "Allah'ın adıyla, Allah'a tevekkül ettim; güç ve kuvvet ancak Allah'tandır.", "Evden çıkarken korunmak için okunur.", "Bu duayı okuyana 'hidayet buldun, kifayet edildin, korundun' denir ve şeytan ondan uzaklaşır."),
        "dua_anxiety_distress" to DuaText("Keder ve üzüntü duası", "Allah'ım! Kederden ve üzüntüden, acizlikten ve tembellikten, cimrilikten ve korkaklıktan, borç yükünden ve insanların baskısından Sana sığınırım.", "Keder, üzüntü, borç ve ruhsal sıkıntı anlarında.", "Peygamber ﷺ bu duayı sıkça okurdu — keder, tembellik ve borçtan sığınmak için."),
        "dua_sayyidul_istighfar" to DuaText("İstiğfarın efendisi (Seyyidü'l-İstiğfar)", "Allah'ım! Sen benim Rabbimsin, Senden başka ilah yoktur. Beni Sen yarattın, ben Senin kulunum. Gücüm yettiğince ahdine ve vaadine bağlıyım. İşlediğim kötülüğün şerrinden Sana sığınırım. Bana verdiğin nimeti itiraf ederim, günahımı da itiraf ederim; beni bağışla, çünkü günahları ancak Sen bağışlarsın.", "Sabah ve akşam okunur — Peygamber'in ﷺ öğrettiği en faziletli tövbe duası.", "Bunu akşam kesin bir inançla okuyup o gece ölen kimse cennete girer; sabah okuyana da aynı fazilet vardır."),
        "dua_parents" to DuaText("Anne-baba için dua", "Rabbim! Onlar beni küçükken nasıl yetiştirdilerse, Sen de onlara öylece merhamet et.", "Anne-babanın küçükken verdiği emeğe karşılık Kur'an'daki dua.", "Allah, ana-baba için bu duayı bizzat Kur'an'da emretmiştir."),
        "dua_entering_mosque" to DuaText("Camiye girerken", "Allah'ım! Bana rahmet kapılarını aç.", "Camiye sağ ayakla girerken okunur.", "Peygamber ﷺ camiye girerken bu duayı öğretmiştir."),
        "dua_morning_asbahna" to DuaText("Sabah zikri", "Sabaha erdik, mülk de Allah'ın olarak sabaha erdi. Hamd Allah'a mahsustur. Allah'tan başka ilah yoktur, O tektir, ortağı yoktur. Mülk O'nundur, hamd O'nadır, O her şeye kadirdir.", "Sabah vakti okunan sünnet dua.", "Güne Allah'ın mülkünü ve tevhidini ikrar ederek başlamak."),
        "dua_evening_amsayna" to DuaText("Akşam zikri", "Akşama erdik, mülk de Allah'ın olarak akşama erdi. Hamd Allah'a mahsustur. Allah'tan başka ilah yoktur, O tektir, ortağı yoktur. Mülk O'nundur, hamd O'nadır, O her şeye kadirdir.", "Akşam vakti okunan sünnet dua.", "Geceye Allah'ın mülkünü ve tevhidini ikrar ederek başlamak."),
        "dua_bismillah_la_yadurru" to DuaText("Her türlü zarardan korunma", "İsmiyle birlikte yerde ve gökte hiçbir şeyin zarar veremeyeceği Allah'ın adıyla; O işitendir, bilendir.", "Sabah ve akşam üç kez okunur.", "Bunu sabah-akşam üç kez okuyanı hiçbir şey zarara uğratamaz."),
        "dua_raditu_billahi" to DuaText("Allah'tan razı olmak", "Rab olarak Allah'tan, din olarak İslam'dan, peygamber olarak Muhammed'den (ﷺ) razı oldum.", "Sabah ve akşam üç kez okunur.", "Bunu okuyanı Allah kıyamet günü razı etmeyi Kendine borç kılar."),
        "dua_hasbiyallah" to DuaText("Allah bana yeter", "Allah bana yeter, O'ndan başka ilah yoktur. Ben O'na tevekkül ettim, O büyük Arş'ın Rabbidir.", "Sabah ve akşam yedi kez okunur.", "Kur'an ayetidir — dünya ve ahiret sıkıntısına yeter."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("Sübhanallahi ve bihamdihi", "Allah'ı hamd ile tesbih ederim.", "Günde yüz kez okunur.", "Bunu yüz kez okuyanın günahları deniz köpüğü kadar da olsa dökülür."),
        "dua_tahleel_100" to DuaText("Günde yüz kez kelime-i tevhid", "Allah'tan başka ilah yoktur, tektir, ortağı yoktur. Mülk O'nundur, hamd O'nadır, O her şeye kadirdir.", "Günde yüz kez okumanın büyük fazileti vardır.", "On köle azat etmiş gibi sevap yazılır, yüz iyilik yazılır, yüz günahı silinir ve o gün akşama kadar şeytandan korunmuş olur."),
        "dua_leaving_mosque" to DuaText("Camiden çıkarken", "Allah'ım! Senden lütfunu istiyorum.", "Camiden sol ayakla çıkarken okunur.", "Camiden çıkarken Allah'ın lütuf ve rızkını istemek."),
        "dua_after_adhan" to DuaText("Ezandan sonra", "Allah'ım! Bu eksiksiz davetin ve kılınacak namazın Rabbi! Muhammed'e vesileyi ve fazileti ver, onu, kendisine vaad ettiğin makam-ı mahmuda ulaştır.", "Ezan bittikten hemen sonra okunur.", "Bunu okuyana kıyamet günü Peygamber'in ﷺ şefaati helal olur."),
        "dua_after_salah_istighfar" to DuaText("Farz namazdan sonra", "Estağfirullah (üç kez). Allah'ım! Sen selamsın, selam Sendendir; ey azamet ve ikram sahibi, Sen yücesin.", "Namazdan selam verir vermez okunur.", "Peygamber ﷺ her farz namazdan sonra bunu okurdu."),
        "dua_after_salah_help_dhikr" to DuaText("Allah'ım, zikrine yardım et", "Allah'ım! Seni anmama, Sana şükretmeme ve Sana güzelce ibadet etmeme yardım et.", "Her namazdan sonra — Peygamber'in ﷺ Muaz'a (r.a.) vasiyeti.", "İbadette kararlılık ve mükemmellik için özel bir nebevi tavsiye."),
        "dua_ayatul_kursi" to DuaText("Namazdan sonra Ayete'l-Kürsi", "Allah, O'ndan başka ilah yoktur; diridir, kayyumdur. O'nu ne uyuklama tutar ne de uyku. Göklerde ve yerde ne varsa O'nundur. İzni olmadan O'nun katında kim şefaat edebilir? Onların önündekini ve arkasındakini bilir. O'nun ilminden, dilediği kadarından başka hiçbir şeyi kavrayamazlar. Kürsüsü gökleri ve yeri kaplamıştır, onları koruyup gözetmek O'na ağır gelmez. O yücedir, büyüktür.", "Her farz namazdan sonra ve uyumadan önce okunur.", "Her farz namazdan sonra okuyanı cennete girmekten sadece ölüm alıkoyar; uyumadan önce okuyan sabaha kadar korunur."),
        "dua_before_sleep" to DuaText("Uyumadan önce", "Allah'ım! Senin adınla ölür (uyur) ve dirilirim (uyanırım).", "Yatağa uzandıktan sonra okunur.", "Peygamber ﷺ uyumadan önce bunu okurdu."),
        "dua_sleep_tasbeeh" to DuaText("Uyumadan önce Fatıma tesbihi", "Sübhanallah (33), Elhamdülillah (33), Allahu ekber (34).", "Uyumadan önce — Peygamber ﷺ bunu Fatıma ve Ali'ye (r.a.) öğretmiştir.", "Peygamber ﷺ: Bu ikiniz için bir hizmetçiden daha hayırlıdır, buyurmuştur."),
        "dua_sleep_qina_adhab" to DuaText("Azaptan korunma", "Allah'ım! Kullarını dirilteceğin gün beni azabından koru.", "Sağ el yanağın altına konur, üç kez okunur.", "Uyumadan önce ölümü ve ahireti hatırlatan bir uyarı."),
        "dua_bad_dream" to DuaText("Kötü rüya görünce", "Kovulmuş şeytandan Allah'a sığınırım.", "Kötü rüya görünce sol tarafa üç kez üflenir, sonra diğer yana dönülür.", "Bu rüya ona zarar vermez ve kimseye anlatılmaz."),
        "dua_yunus" to DuaText("Hz. Yunus'un (a.s.) duası", "Senden başka ilah yoktur, Sen münezzehsin; gerçekten ben zalimlerden oldum.", "Hz. Yunus'un (a.s.) balığın karnındaki duası — her sıkıntı için.", "Bir Müslüman bunu herhangi bir konuda dua ederse Allah mutlaka kabul eder."),
        "dua_karb" to DuaText("Şiddetli sıkıntı duası", "Allah'tan başka ilah yoktur, O büyüktür, halimdir. Allah'tan başka ilah yoktur, O büyük Arş'ın Rabbidir. Allah'tan başka ilah yoktur, göklerin, yerin ve şerefli Arş'ın Rabbidir.", "Şiddetli sıkıntı ve darlık anında okunur.", "Peygamber ﷺ sıkıntı anında bunu okurdu."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ey Hayy, ey Kayyum", "Ey diri ve her şeyi ayakta tutan Allah'ım! Rahmetinle yardım isterim.", "İş ağırlaştığında okunur.", "Peygamber ﷺ bir mesele onu üzünce bunu okurdu."),
        "dua_hasbunallah" to DuaText("Hasbunallahu ve ni'mel vekil", "Allah bize yeter, O ne güzel vekildir.", "Düşman korkusu veya büyük tehlike anında okunur.", "İbrahim (a.s.) ateşe atılırken, Peygamber ﷺ ise tehlike anında bunu söylemiştir."),
        "dua_entering_home" to DuaText("Eve girerken", "Allah'ın adıyla girdik, Allah'ın adıyla çıktık, Rabbimiz Allah'a tevekkül ettik.", "Eve girerken Allah'ın adını anarak ve selam vererek okunur.", "Evine girerken ve yemek yerken Allah'ı anan kimseye şeytan: 'Sizin için ne kalacak yer ne de yemek var' der."),
        "dua_travel" to DuaText("Yolculuk duası", "Bunu bizim hizmetimize vereni tesbih ederiz, yoksa biz buna güç yetiremezdik. Şüphesiz biz Rabbimize döneceğiz.", "Bineğe binerken üç kez tekbir getirdikten sonra okunur.", "Korunma ve bereket için sünnet olan yolculuk duası."),
        "dua_entering_market" to DuaText("Çarşıya girerken", "Allah'tan başka ilah yoktur, tektir, ortağı yoktur. Mülk O'nundur, hamd O'nadır; diriltir, öldürür, O diridir, ölmez; hayır O'nun elindedir, O her şeye kadirdir.", "Çarşıya girerken okunur.", "Hadiste bunun için büyük bir sevap (milyonlarca iyilik) bildirilmiştir."),
        "dua_adam_forgiveness" to DuaText("Hz. Âdem'in (a.s.) duası", "Rabbimiz! Kendimize zulmettik; eğer bizi bağışlamaz ve bize merhamet etmezsen mutlaka ziyan edenlerden oluruz.", "Hz. Âdem ve Havva'nın (a.s.) tövbesi.", "İnsanlık tarihindeki ilk tövbe — Allah tarafından kabul edilmiştir."),
        "dua_abu_bakr" to DuaText("Peygamber'in Ebu Bekir'e öğrettiği dua", "Allah'ım! Nefsime çokça zulmettim; günahları ancak Sen bağışlarsın; beni katından bir mağfiretle bağışla ve bana merhamet et, şüphesiz Sen çok bağışlayan, çok merhamet edensin.", "Peygamber ﷺ bunu Ebu Bekir'e (r.a.) namazda okuması için öğretmiştir.", "Namazın sonunda okunan sünnet bir dua."),
        "dua_astaghfirullah_atubu" to DuaText("Günlük istiğfar", "Allah'tan bağışlanma dilerim ve O'na tövbe ederim.", "Peygamber ﷺ günde yetmiş defadan fazla istiğfar ederdi.", "Peygamber ﷺ: Ben günde yetmiş defadan fazla Allah'a istiğfar edip tövbe ederim, buyurmuştur."),
        "dua_laylatul_qadr" to DuaText("Kadir gecesi duası", "Allah'ım! Sen çok affedicisin, affetmeyi seversin; beni de affet.", "Peygamber ﷺ bunu Aişe'ye (r.a.) Kadir gecesi için öğretmiştir.", "Ramazan'ın son on gününde ve Kadir gecesine özel bir dua."),
        "dua_family_coolness" to DuaText("Aileden göz aydınlığı", "Rabbimiz! Bize eşlerimizden ve çocuklarımızdan göz aydınlığı olacak nesiller bağışla ve bizi takva sahiplerine önder kıl.", "Salih eş ve nesil için Kur'an'daki dua.", "Ev huzuru ve salih nesil için okunur."),
        "dua_righteous_children" to DuaText("Salih nesil duası", "Rabbim! Bana katından tertemiz bir nesil bağışla; şüphesiz Sen duayı işitensin.", "Hz. Zekeriyya'nın (a.s.) duası.", "Evlat isteği için Kur'an'daki dua."),
        "dua_ibrahim_prayer_family" to DuaText("Namazı ikame etmek", "Rabbim! Beni namazı devamlı kılan biri eyle, soyumdan da böyle kimseler yarat. Rabbimiz! Duamı kabul buyur. Rabbimiz! Hesabın görüleceği gün beni, ana-babamı ve müminleri bağışla.", "Hz. İbrahim'in (a.s.) kendisi ve nesli için duası.", "Genellikle namazın sonunda okunur."),
        "dua_newlywed" to DuaText("Yeni evlilere tebrik", "Allah sana bereket versin, üzerine bereket indirsin ve ikinizi hayırda bir araya getirsin.", "Evlenen kişiye söylenir.", "Sünnet olan evlilik tebriği."),
        "dua_before_eating" to DuaText("Yemekten önce", "Bismillah. (Unutulursa:) Başında da sonunda da Allah'ın adıyla.", "Yemekten önce, unutulursa yeme sırasında okunur.", "Besmele çekilirse şeytan yemeğe ortak olamaz."),
        "dua_after_eating" to DuaText("Yemekten sonra", "Bana bu yemeği yediren ve gücüm ve kuvvetim olmaksızın rızık veren Allah'a hamd olsun.", "Yemek bittikten sonra okunur.", "Bunu okuyanın geçmiş günahları bağışlanır."),
        "dua_host" to DuaText("Ev sahibi için dua", "Allah'ım! Onlara rızık olarak verdiğinde bereket ver, onları bağışla ve onlara merhamet et.", "Bir kişinin evinde yemek yedikten sonra ev sahibine okunur.", "Sünnete uygun şekilde ev sahibine teşekkür."),
        "dua_breaking_fast" to DuaText("İftar duası", "Susuzluk gitti, damarlar ıslandı ve inşallah sevap sabit oldu.", "İftar anında okunur.", "Peygamber ﷺ iftar ederken bunu okurdu."),
        "dua_new_clothes" to DuaText("Yeni elbise giyerken", "Allah'ım! Hamd Sanadır, bunu bana Sen giydirdin; hayrını ve ne için yapıldıysa onun hayrını isterim, şerrinden ve ne için yapıldıysa onun şerrinden Sana sığınırım.", "Yeni elbise giyerken, elbisenin adını anarak okunur.", "Peygamber ﷺ yeni elbise giyerken bunu okurdu."),
        "dua_rabbana_atina" to DuaText("Dünya ve ahiretin hayrı", "Rabbimiz! Bize dünyada iyilik, ahirette de iyilik ver; bizi ateş azabından koru.", "Peygamber'in ﷺ en çok okuduğu dua.", "Dünya ve ahiretteki her hayrı kapsayan kapsamlı bir dua."),
        "dua_rabbi_zidni_ilma" to DuaText("İlmin artması", "Rabbim! İlmimi artır.", "İlmin artması için okunur.", "Allah, Peygamber'e ﷺ yalnızca ilimde artış istemesini emretmiştir."),
        "dua_musa_sharh_sadr" to DuaText("Göğsün açılması (Hz. Musa'nın duası)", "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimdeki düğümü çöz ki sözümü anlasınlar.", "Sınav, konuşma veya zor bir işten önce.", "Hz. Musa'nın (a.s.) duası — kalp huzuru ve işin kolaylaşması için."),
        "dua_la_tuzigh" to DuaText("Kalbin sebatı", "Rabbimiz! Bizi hidayete erdirdikten sonra kalplerimizi eğriltme, katından bize rahmet bağışla; şüphesiz Sen çok bağışlayansın.", "Hidayet üzere sebat için okunur.", "İmanda sebat duası."),
        "dua_ya_muqallib" to DuaText("Ey kalpleri evirip çeviren", "Ey kalpleri evirip çeviren Allah'ım! Kalbimi dinin üzere sabit kıl.", "Peygamber ﷺ bunu sıkça okurdu.", "Ümmü Seleme'ye (r.a.) göre Peygamber'in ﷺ en çok okuduğu dualardan biri."),
        "dua_la_tuakhidhna" to DuaText("Bakara suresinin sonu", "Rabbimiz! Unutursak veya hataya düşersek bizi sorumlu tutma. Rabbimiz! Bizden öncekilere yüklediğin gibi bize ağır yük yükleme. Rabbimiz! Gücümüzün yetmeyeceği şeyi bize taşıtma; bizi affet, bağışla ve bize merhamet et; Sen bizim Mevlamızsın, kâfirler topluluğuna karşı bize yardım et.", "Uyumadan önce — Bakara suresinin son iki ayeti.", "Bunu geceleyin okuyana o gece için yeter."),
        "dua_visiting_sick" to DuaText("Hasta ziyareti", "Büyük Arş'ın Rabbi olan yüce Allah'tan sana şifa vermesini dilerim.", "Hasta ziyaretinde yedi kez okunur.", "Eceli gelmemişse Allah ona şifa verir."),
        "dua_ruqyah_pain" to DuaText("Bedendeki ağrı için", "Hissettiğim ve çekindiğim şeyin kötülüğünden Allah'a ve O'nun kudretine sığınırım.", "Ağrıyan yere el konur, üç kez besmele sonra yedi kez bu dua okunur.", "Peygamber ﷺ bunu Osman b. Ebi'l-As'a (r.a.) ağrısı için öğretmiştir."),
        "dua_ruqyah_nabawi" to DuaText("Peygamber'in hasta için ruqyesi", "Allah'ım! İnsanların Rabbi, sıkıntıyı gider; şifa veren Sensin, Senin şifandan başka şifa yoktur; hiçbir hastalık bırakmayan bir şifa ver.", "Hastaya el sürülerek okunur.", "Peygamber ﷺ ailesini ziyaret ederken bunu okurdu."),
        "dua_kalimat_tammat" to DuaText("Allah'ın tam kelimelerine sığınma", "Yarattıklarının şerrinden Allah'ın tam kelimelerine sığınırım.", "Bir yere konaklarken veya akşam okunur.", "Bir yere konaklayıp bunu okuyan kimseye, oradan ayrılana kadar hiçbir şey zarar vermez."),
        "dua_evil_eye" to DuaText("Çocukları nazardan koruma", "Sizi Allah'ın tam kelimeleriyle her şeytandan, zararlı şeyden ve nazar değen gözden korurum.", "Peygamber ﷺ bunu Hasan ve Hüseyin'e (r.a.) okurdu.", "Çocukları nazar ve kötülükten korumak için sünnet dua."),
        "dua_seeing_afflicted" to DuaText("Musibete uğramış birini görünce", "Seni sınadığı şeyden beni koruyan ve yarattıklarının çoğuna göre beni üstün kılan Allah'a hamd olsun.", "Musibete uğramış birini görünce (kalpten okunur).", "Bunu okuyan kişi o musibetten korunur."),
        "dua_istikhara" to DuaText("İstihare namazı duası", "Allah'ım! İlminle senden hayır dilerim, kudretinle senden güç isterim, senin büyük lütfundan isterim. Çünkü Sen güç yetirirsin, ben yetiremem; Sen bilirsin, ben bilemem; gaybı bilen Sensin. Allah'ım, eğer bu iş dinim, dünyam ve akıbetim için hayırlıysa onu bana takdir et, kolaylaştır ve bereketli kıl; eğer şerliyse onu benden, beni de ondan uzaklaştır, hayrı nerede olursa olsun bana takdir et ve beni ona razı kıl.", "Mubah bir işte hayır istenirken iki rekat namazdan sonra okunur.", "Peygamber ﷺ ashabına istiharayı Kur'an'dan bir sure öğretir gibi öğretirdi."),
        "dua_allahumma_bika_asbahna" to DuaText("Allah'ım, Seninle sabahladık", "Allah'ım! Seninle sabahladık, Seninle akşamladık; Seninle yaşar, Seninle ölürüz; dönüş de Sanadır.", "Sabah okunur.", "Peygamber ﷺ bunu ashabına sabah-akşam öğretirdi."),
        "dua_allahumma_bika_amsayna" to DuaText("Allah'ım, Seninle akşamladık", "Allah'ım! Seninle akşamladık, Seninle sabahladık; Seninle yaşar, Seninle ölürüz; dönüş de Sanadır.", "Akşam okunur.", "Peygamber ﷺ bunu ashabına sabah-akşam öğretirdi."),
        "dua_afiyah_morning" to DuaText("Afiyet duası", "Allah'ım! Dünyada ve ahirette senden af ve afiyet dilerim.", "Peygamber ﷺ sabah-akşam bunu terk etmezdi.", "Hiç kimseye afiyetten daha hayırlı bir şey verilmemiştir."),
        "dua_afini_fi_badani" to DuaText("Beden, kulak ve gözde afiyet", "Allah'ım! Bedenimde bana afiyet ver, kulağımda bana afiyet ver, gözümde bana afiyet ver; Senden başka ilah yoktur.", "Sabah-akşam üç kez okunur.", "Sağlık ve duyuları korumak için okunur."),
        "dua_ya_hayyu_aslih" to DuaText("Bütün işlerimi ıslah et", "Ey diri ve her şeyi ayakta tutan Allah'ım! Rahmetinle yardım isterim; bütün işlerimi ıslah et ve beni bir göz açıp kapayıncaya kadar bile nefsime bırakma.", "Peygamber ﷺ Fatıma'ya (r.a.) sabah-akşam okumasını tavsiye etmiştir.", "Her işte Allah'ın yardımını istemek."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Cüveyriye'nin (r.a.) tesbihi", "Allah'ı, yarattıkları sayısınca, kendi rızası kadar, Arş'ının ağırlığınca ve kelimelerinin sayısınca hamd ile tesbih ederim.", "Sabah üç kez okunur — uzun saatler zikretmeye denk gelir.", "Bu dört kelime üç kez, sabahtan öğlene kadar yapılan zikirden daha ağırdır."),
        "dua_salawat" to DuaText("İbrahimî salavat", "Allah'ım! İbrahim'e ve âline salat ettiğin gibi Muhammed'e ve âline de salat et; şüphesiz Sen övülmeye layıksın, şanı yücesin. Allah'ım! İbrahim'e ve âline bereket verdiğin gibi Muhammed'e ve âline de bereket ver; şüphesiz Sen övülmeye layıksın, şanı yücesin.", "Namazda ve her zaman okunur.", "Peygamber'e ﷺ bir kez salavat getirene Allah on kat salat eder."),
        "dua_wudu_after" to DuaText("Abdestten sonra", "Şehadet ederim ki Allah'tan başka ilah yoktur, tektir, ortağı yoktur; ve şehadet ederim ki Muhammed O'nun kulu ve elçisidir. Allah'ım! Beni çok tövbe edenlerden ve çok temizlenenlerden kıl.", "Abdest tamamlandıktan sonra okunur.", "Cennetin sekiz kapısı ona açılır, dilediğinden girer."),
        "dua_wudu_before" to DuaText("Abdestten önce", "Bismillah.", "Abdeste başlarken okunur.", "Allah'ın adını anmayanın abdesti (kâmil olarak) yoktur."),
        "dua_istiftah" to DuaText("İftitah duası", "Allah'ım! Seni hamd ile tesbih ederim, adın mübarektir, şanın yücedir; Senden başka ilah yoktur.", "Namazın başında tekbirden sonra okunur.", "Sünnet olan iftitah duası."),
        "dua_ruku" to DuaText("Rükûda", "Yüce Rabbimi tesbih ederim.", "Rükûda en az üç kez okunur.", "Rükû tesbihidir."),
        "dua_sujood" to DuaText("Secdede", "Yüce olan Rabbimi tesbih ederim.", "Secdede en az üç kez okunur.", "Kul, secdedeyken Rabbine en yakın olur."),
        "dua_rising_ruku" to DuaText("Rükûdan kalkarken", "Allah, kendisine hamd edeni işitir. Rabbimiz, hamd Sanadır.", "Rükûdan kalkıp doğrulurken okunur.", "Sözü meleklerin sözüne denk gelen kişinin geçmiş günahları bağışlanır."),
        "dua_between_sajdas" to DuaText("İki secde arasında", "Rabbim beni bağışla, Rabbim beni bağışla.", "İki secde arasındaki oturuşta okunur.", "Sünnet olan oturuş duası."),
        "dua_before_salam_four" to DuaText("Selam vermeden önce dört şeyden sığınma", "Allah'ım! Cehennem azabından, kabir azabından, hayat ve ölüm fitnesinden ve Mesih Deccal'in fitnesinin şerrinden Sana sığınırım.", "Son teşehhüt ve salavattan sonra, selamdan önce okunur.", "Peygamber ﷺ bu dört şeyden sığınmayı emretmiştir."),
        "dua_qunoot_witr" to DuaText("Vitirde kunut duası", "Allah'ım! Hidayet ettiklerin arasında beni de hidayete erdir, afiyet verdiklerin arasında bana da afiyet ver, dost edindiklerin arasında beni de dost edin, bana verdiğini bereketli kıl, takdir ettiğin şerden beni koru; çünkü Sen hükmedersin, aleyhine hükmedilmez; Senin dost edindiğin zelil olmaz; Rabbimiz, Sen yücesin, şanın büyüktür.", "Vitir namazında — Peygamber ﷺ bunu Hasan b. Ali'ye (r.a.) öğretmiştir.", "Vitirde okunan sünnet kunut duası."),
        "dua_qunoot_hanafi" to DuaText("Kunut duası (Allahümme inna nesteinüke)", "Allah'ım! Senden yardım ister, bağışlanma dileriz; Sana iman eder, Sana tevekkül ederiz; Seni bütün hayırla övüp Sana şükrederiz, Seni inkâr etmeyiz; Sana isyan edeni terk eder ve ondan ayrılırız. Allah'ım! Yalnız Sana ibadet eder, Senin için namaz kılar ve secde ederiz; Sana koşar ve hizmet ederiz; rahmetini umar, azabından korkarız; şüphesiz Senin azabın kâfirlere ulaşır.", "Vitirde — Hanefi mezhebinde okunur.", "Hz. Ömer'den (r.a.) kunut olarak rivayet edilmiştir."),
        "dua_sleep_aslamtu" to DuaText("Uyumadan önce son söz", "Allah'ım! Nefsimi Sana teslim ettim, işimi Sana havale ettim, sırtımı Sana dayadım; rağbet ve korkuyla Sanayım, Senden kaçış ve sığınış ancak Sanadır; indirdiğin kitabına ve gönderdiğin peygamberine iman ettim.", "Abdest alıp sağ tarafa yatınca — en son söylenen söz.", "O gece ölürse fıtrat üzere ölmüş olur."),
        "dua_waking_night" to DuaText("Geceleyin uyanınca", "Allah'tan başka ilah yoktur, tektir, ortağı yoktur; mülk O'nundur, hamd O'nadır, O her şeye kadirdir. Hamd Allah'a mahsustur, Allah münezzehtir, Allah'tan başka ilah yoktur, Allah büyüktür, güç ve kuvvet ancak Allah'tandır. Allah'ım, beni bağışla.", "Geceleyin uyanınca okunur.", "Duası kabul olur; abdest alıp namaz kılarsa namazı da kabul edilir."),
        "dua_hamm_ibn_masud" to DuaText("Keder duası (İbn Mesud rivayeti)", "Allah'ım! Ben Senin kulunum, kulunun oğluyum, cariyenin oğluyum; alnım Senin elindedir, hakkımda hükmün geçerlidir, hakkımdaki kararın adildir. Kendini isimlendirdiğin, kitabında indirdiğin, yarattıklarından birine öğrettiğin veya kendi katındaki gayb ilminde sakladığın her ismin hakkı için, Kur'an'ı kalbimin baharı, göğsümün nuru, üzüntümün gidericisi ve kederimin sona erdiricisi kıl.", "Keder ve üzüntü anında — Allah kederini sevince çevirir.", "Allah onun kederini ve üzüntüsünü giderip yerine sevinç verir."),
        "dua_difficulty_sahl" to DuaText("Zorluk anında", "Allah'ım! Senin kolaylaştırdığından başka kolay yoktur; Sen dilersen zoru kolaylaştırırsın.", "Zor bir işle karşılaşınca okunur.", "Sınavları ve zorlukları kolaylaştırmak için okunur."),
        "dua_musibah" to DuaText("Musibet anında (İstirca)", "Şüphesiz biz Allah'a aitiz ve şüphesiz O'na döneceğiz. Allah'ım! Musibetimde bana ecrini ver ve bana ondan daha hayırlısını ver.", "Herhangi bir kayıp veya musibet anında.", "Allah ondan daha hayırlısını verir — Ümmü Seleme'nin (r.a.) başına geldiği gibi."),
        "dua_debt" to DuaText("Borçtan kurtulma", "Allah'ım! Helalinle beni haramından koru, lütfunla beni Senden başkasına muhtaç etme.", "Borcu ödemek için — Peygamber ﷺ bunu Ali'ye (r.a.) öğretmiştir.", "Dağ kadar borcu olsa bile Allah onu öder."),
        "dua_anger" to DuaText("Öfkelenince", "Kovulmuş şeytandan Allah'a sığınırım.", "Öfke anında okunur.", "Peygamber ﷺ: Bunu söylese öfkesi giderdi, buyurmuştur."),
        "dua_waswasa" to DuaText("İman vesvesesine karşı", "Allah'a ve elçilerine iman ettim.", "Şeytanın iman konusunda vesvese vermesi anında.", "Bunu söyleyip vesveseyi düşünmeyi bırakır."),
        "dua_travel_full" to DuaText("Tam yolculuk duası", "Allah'ım! Bu yolculuğumuzda Senden iyilik ve takva, razı olacağın ameller dileriz. Allah'ım! Bu yolculuğumuzu bize kolaylaştır ve uzaklığını üzerimizden dür. Allah'ım! Sen yolculukta arkadaş, geride kalanlar üzerinde vekilsin.", "Yola çıkarken 'sübhanellezi sehhara' duasından sonra okunur.", "Tam ve sünnet olan yolculuk duası."),
        "dua_return_travel" to DuaText("Yolculuktan dönerken", "Dönenleriz, tövbe edenleriz, ibadet edenleriz, Rabbimize hamd edenleriz.", "Yolculuktan dönerken okunur.", "Peygamber ﷺ yolculuktan dönerken bunu okurdu."),
        "dua_farewell_traveller" to DuaText("Yolcuya veda", "Dinini, emanetini ve amellerinin sonucunu Allah'a emanet ediyorum.", "Yola çıkan kişiye veda ederken söylenir.", "Allah'a emanet edilen şey zayi olmaz."),
        "dua_entering_town" to DuaText("Yeni bir yere inerken", "Yarattıklarının şerrinden Allah'ın tam kelimelerine sığınırım.", "Yeni bir yere veya şehre inerken okunur.", "O yerden ayrılana kadar hiçbir şey ona zarar vermez."),
        "dua_boarding_ship" to DuaText("Gemiye binerken", "Onun yüzmesi de durması da Allah'ın adıyladır; şüphesiz Rabbim çok bağışlayan, çok merhamet edendir.", "Gemiye binerken — Hz. Nuh'un (a.s.) sözü.", "Kur'an ayeti — Hz. Nuh'un (a.s.) gemi duası."),
        "dua_istighfar_hayyul_qayyum" to DuaText("El-Hayyü'l-Kayyum ile istiğfar", "Kendisinden başka ilah olmayan, diri ve her şeyi ayakta tutan Allah'tan bağışlanma dilerim ve O'na tövbe ederim.", "Tövbe için okunur.", "Savaştan kaçmış olsa bile günahları bağışlanır."),
        "dua_rabbighfir_warham" to DuaText("Rabbim bağışla ve merhamet et", "Rabbim! Bağışla ve merhamet et, Sen merhamet edenlerin en hayırlısısın.", "Kur'an'daki bağışlanma ve merhamet duası.", "Müminun suresinin son ayeti."),
        "dua_majlis_kaffarah" to DuaText("Meclisin kefareti", "Seni hamdinle tesbih ederim Allah'ım; şehadet ederim ki Senden başka ilah yoktur, Senden bağışlanma diler ve Sana tövbe ederim.", "Bir meclisten kalkarken okunur.", "Mecliste geçen boş sözlerin kefareti."),
        "dua_jami_forgiveness" to DuaText("Kapsamlı bağışlanma duası", "Allah'ım! Hatamı, cahilliğimi ve işimdeki aşırılığımı bağışla; benden daha iyi bildiğin her şeyi de bağışla.", "Peygamber'in ﷺ sıkça okuduğu kapsamlı bir dua.", "Peygamber'in ﷺ çokça okuduğu geniş kapsamlı bir dua."),
        "dua_parents_nuh" to DuaText("Hz. Nuh'un (a.s.) ana-baba duası", "Rabbim! Beni, ana-babamı, mümin olarak evime gireni ve bütün mümin erkek ve kadınları bağışla.", "Ana-baba ve müminler için.", "Hz. Nuh'un (a.s.) duası."),
        "dua_shukr_parents" to DuaText("Ana-baba nimetine şükür ve salih nesil", "Rabbim! Bana ve ana-babama verdiğin nimete şükretmemi ve razı olacağın salih ameller işlememi nasip et; neslimi de benim için ıslah et; şüphesiz Sana tövbe ettim ve gerçekten Müslümanlardanım.", "Kırk yaşına erenler için Kur'an'daki dua.", "Nimete şükür, salih amel ve nesli ıslah etmeyi tek bir duada toplar."),
        "dua_intimacy" to DuaText("Eşler arasında yakınlaşmadan önce", "Bismillah. Allah'ım! Bizi şeytandan uzak tut, bize verdiğin rızıktan da şeytanı uzaklaştır.", "Eşler yakınlaşmadan önce okunur.", "Eğer bu birleşmeden bir çocuk takdir edilirse, şeytan ona asla zarar veremez."),
        "dua_ibrahim_children_protection" to DuaText("Beldeyi ve nesli koruma", "Rabbim! Bu beldeyi güvenli kıl, beni ve oğullarımı putlara tapmaktan uzak tut.", "Hz. İbrahim'in (a.s.) beldesi ve nesli için duası.", "Tevhid üzere sebat duası."),
        "dua_drinking_milk" to DuaText("Süt içerken", "Allah'ım! Bunda bize bereket ver ve bize daha fazlasını ver.", "Süt içerken okunur.", "Süt hem yemek hem içmek yerine geçer."),
        "dua_iftar_host" to DuaText("Başka birinin evinde iftar ederken", "Oruçlular yanınızda iftar etsin, yemeğinizi iyi kişiler yesin, melekler size dua etsin.", "Başka birinin evinde iftar ederken okunur.", "Peygamber'in ﷺ ev sahibi için duası."),
        "dua_seeing_first_fruit" to DuaText("Mevsimin ilk meyvesini görünce", "Allah'ım! Meyvelerimizde bize bereket ver, şehrimizde bize bereket ver, ölçeğimizde ve müddümüzde bize bereket ver.", "Mevsimin ilk meyvesini görünce okunur.", "Rızık ve beldede bereket duası."),
        "dua_good_news" to DuaText("Sevindirici haber duyunca", "Nimetiyle salih amellerin tamamlandığı Allah'a hamd olsun.", "Sevindirici haber duyunca (ve şükür secdesi yaparken).", "Peygamber ﷺ sevdiği bir şey gördüğünde bunu söylerdi."),
        "dua_looking_mirror" to DuaText("Aynaya bakarken", "Allah'ım! Yaratılışımı güzelleştirdiğin gibi ahlakımı da güzelleştir.", "Aynaya bakarken okunur.", "Peygamber ﷺ bu duayı okurdu."),
        "dua_rabbana_taqabbal" to DuaText("Amellerin kabulü", "Rabbimiz! Bizden kabul et, şüphesiz Sen işitensin, bilensin. Tövbemizi kabul et, şüphesiz Sen tövbeleri çok kabul edensin, çok merhamet edensin.", "Hz. İbrahim ve İsmail'in (a.s.) Kâbe'yi inşa ederken duası.", "Bir ameli tamamladıktan sonra kabulü için okunan dua."),
    )
}
